"""kernels/muse_bf16_proj/measure_cheap_v1.py (C23, MEASUREMENT-ONLY, generated by tools/gen_measure_cheap_v1.py).

No GPU: file rules, kernel_fn / prepare are director_v1b verbatim, in sync with the generator, candidate table + fixup kernel are director_v2's, the correctness check agrees with
the organisers' check_implementation, the render stays under 14 KB in the worst case, the estimated-score arithmetic.
Dev GPU (RTX 2060, BF16 emulated): the whole study end to end on a reduced shape list.
Run: tools/heavy.sh .venv/bin/python -m pytest -q tests/test_measure_cheap_v1.py"""
import importlib.util
import re
import sys
from pathlib import Path

import pytest
import torch

ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(ROOT))
from tools import local_check as lc  # noqa: E402

PROBLEM = "muse_bf16_proj"
MEAS = ROOT / "kernels" / PROBLEM / "measure_cheap_v1.py"
V1B = ROOT / "kernels" / PROBLEM / "director_v1b.py"
V2 = ROOT / "kernels" / PROBLEM / "director_v2.py"
needs_cuda = pytest.mark.skipif(not torch.cuda.is_available(), reason="needs a CUDA GPU")


def _load(name, path):
    spec = importlib.util.spec_from_file_location(name, path)
    m = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(m)
    return m


@pytest.fixture()
def mod():
    return _load("_measure_cheap_v1", MEAS)


@pytest.fixture(scope="module")
def ref():
    return lc.Loaded(PROBLEM, V1B).ref


def test_source_rules_and_in_sync_with_generator():
    src = MEAS.read_text()
    compile(src, "measure_cheap_v1.py", "exec")
    lines = src.splitlines()
    assert lines[0] == "# okc: problem=muse_bf16_proj" and "MEASUREMENT-ONLY" in lines[1] and "NEVER submit" in lines[1]
    for banned in ("subprocess", "urllib", "requests", "socket", "os.system", "import os", "environ", ".tolist(", "from reference", "import reference"):
        assert banned not in src, banned
    from tools import gen_measure_cheap_v1 as gen
    assert gen.build() == src, "regenerate: .venv/bin/python tools/gen_measure_cheap_v1.py"
    assert "MEASUREMENT-ONLY" not in V2.read_text() and "def _mc_" not in V2.read_text()


def test_kernel_fn_and_prepare_are_v1b_verbatim():
    v = V1B.read_text().splitlines()
    m = MEAS.read_text().splitlines()
    body = m[m.index(v[1]) if v[1] in m else 0:]
    start = next(i for i, line in enumerate(m) if line.startswith('"""bf16_proj candidate v1b'))
    assert m[start:start + len(v) - 1] == v[1:], "v1b is not embedded verbatim"
    assert body


def test_candidates_and_fixup_kernel_are_v2s(mod):
    v2 = _load("_v2_for_meas", V2)
    assert mod._MC_CANDIDATES == v2._CANDIDATES and mod.FIX_WS_FLOATS == v2.FIX_WS_FLOATS and mod.FIX_TILES == v2.FIX_TILES
    import inspect
    a = inspect.getsource(v2._gemv_fix.fn)
    b = inspect.getsource(mod._mc_gemv_fix.fn).replace("_mc_gemv_fix", "_gemv_fix")
    assert a == b


def test_generate_input_recipe_equals_the_reference(mod, ref):
    if not torch.cuda.is_available():
        pytest.skip("cuda")
    for m, layer, dist in ((8, "unpooler", "normal"), (130, "router", "outliers"), (1, "o", "normal")):
        a = mod._tr_generate_input(m, layer, 7, dist, "cuda")
        b = ref.generate_input(m=m, layer=layer, seed=7, dist=dist, device="cuda")
        assert torch.equal(a["x"], b["x"]) and a["config"] == b["config"]


@needs_cuda
@pytest.mark.parametrize("layer,m", [("router", 9), ("unpooler", 8), ("o", 33)])
def test_check_agrees_with_the_organisers(mod, ref, layer, m):
    weights = ref.generate_weights(ref.WEIGHTS_SEED, device="cuda")
    d = ref.generate_input(m=m, layer=layer, seed=2, device="cuda")
    good = ref.ref_kernel(d, weights)
    probes = ref.probe_rows(d["x"])
    assert len(probes)
    tol = 1e-4 if layer == "router" else 1e-2
    for scale in (0.0, 0.3, 0.9, 1.5, 4.0):
        out = good * (1 + scale * tol)                   # uniform error = scale * tol
        want, _ = ref.check_implementation(d, out, weights)
        got, use, _ = mod._mc_check(out, good, d["x"], layer)
        assert want == got, (scale, use)
    bad = good.clone()
    bad[probes[0]] *= 1 + 3e-3                           # one probe row off by 3e-3: tolerated by the L2 bound, not by the probe bound
    want, _ = ref.check_implementation(d, bad, weights)
    got, use, _ = mod._mc_check(bad, good, d["x"], layer)
    assert want == got and not got
    nan = good.clone()
    nan[0, 0] = float("nan")
    assert not mod._mc_check(nan, good, d["x"], layer)[0]
    assert not mod._mc_check(good.float().to(torch.float64), good, d["x"], layer)[0]


def _fake_results(mod, nvar=9):
    res = {}
    for layer in mod._MC_LAYERS:
        for m in mod._MC_MS:
            r = {"board": dict(kind="board", us=10.0 + m / 50, xs=[1.0, 1.0, 1.0], ok=True, use=0.1, why="", status="ok"),
                 "sgl": dict(kind="ref", us=11.0 + m / 40, xs=[0.9, 0.9, 0.9], ok=True, use=0.1, why="", status="ok"),
                 "mm": dict(kind="ref", us=12.0, xs=[0.8, 0.8, 0.8], ok=True, use=0.1, why="", status="ok")}
            if (layer, m) in mod._MC_PRIO:
                for i in range(nvar):
                    r[f"fix.m.{64 + i}.128.64.4.4.g1"] = dict(kind="new", us=5.0 + i, xs=[2.0, 2.1, 1.9], ok=i != 3, use=0.7, why="", status="ok" if i != 5 else "fail Error")
            res[(layer, m)] = r
    return res


def test_render_size_summary_first_and_score(mod):
    text = mod._mc_render(_fake_results(mod), 3.9, "NVIDIA_H200", 250.0)
    assert len(text.encode()) <= 14000
    lines = text.splitlines()
    assert lines[0].startswith("S bf16 cheap v1:") and lines[1].startswith("S us =")
    first_b = next(i for i, line in enumerate(lines) if line.startswith("B "))
    assert all(line.startswith("S ") for line in lines[:first_b])
    assert any("est problem speedup" in line for line in lines[:first_b])
    for line in lines[first_b:]:
        assert re.fullmatch(r"B bf16 \w+ m=\d+ \| \S+ (us=\d+\.\d\d x=\d+\.\d\d( b=\d\.\d\d| BAD\(\d+\.\d\))?|fail .*|skip.*)", line), line
    big = mod._mc_render(_fake_results(mod, nvar=60), 3.9, "NVIDIA_H200", 250.0)
    assert len(big.encode()) <= 14000 and "dropped for the 14 KB cap" in big


def test_score_arithmetic(mod):
    res = _fake_results(mod)
    for layer in mod._MC_LAYERS:
        for m in mod._MC_MS:
            res[(layer, m)]["sgl"]["us"] = 20.0
            res[(layer, m)]["board"]["us"] = 10.0
    sc, parts = mod._mc_score(res, lambda r: r["board"]["us"])
    assert abs(sc - 2.0) < 1e-9 and len(parts) == 6
    assert mod._mc_score({}, lambda r: 1.0)[0] is None


@needs_cuda
def test_end_to_end_on_a_reduced_shape_list(mod, ref, monkeypatch, capsys):
    monkeypatch.setattr(mod, "_triton_ok", lambda d: True)
    monkeypatch.setattr(mod, "_MC_MS", (1, 128))
    monkeypatch.setattr(mod, "_MC_PRIO", (("unpooler", 1), ("router", 1), ("router", 128)))
    weights = ref.generate_weights(ref.WEIGHTS_SEED, device="cuda")
    st = mod.prepare(weights)
    assert "router_hi" in st and "fix_ws" not in st          # the returned state is v1b's
    out = capsys.readouterr().out
    assert "BAD(" not in out, out
    assert any(line.startswith("B bf16 unpooler m=1 | fix.16.32.128.4.4.4.g4 ") for line in out.splitlines())
    assert any(line.startswith("B bf16 router m=128 | fix.m.32.64.32.4.4 ") for line in out.splitlines())
    assert any(line.startswith("B bf16 router m=128 | fix.64.32.128.8.4.3 ") for line in out.splitlines())
    assert any(line.startswith("B bf16 qkv_gate m=128 | mm ") for line in out.splitlines())
    assert len(out.encode()) < 14500
    # nothing the study allocates is left in the state that kernel_fn uses
    d = ref.generate_input(m=8, layer="router", seed=1, device="cuda")
    assert ref.check_implementation(d, mod.kernel_fn(d, st), weights)[0]
